  ('fd0dae31-24c2-5370-aa47-4847d9f1440d', 'alianca-varietal-tinto', 'Aliança Varietal Tinto', 'Trio de varietais da Serra Gaúcha', 'Elaborado por Vinícola Nova Aliança (Serra Gaúcha, Brasil) a partir de Tannat, Cabernet Sauvignon e Merlot. No nariz, amora, especiarias e couro; cassis, pimentão e um toque de cedro. Na boca, estrutura marcante, taninos presentes. Disponível em Tannat, Cabernet Sauvignon e Merlot.', '2df85ef0-df3f-5ed0-9dd9-b6e049b22e80', 'b4c08ac6-d72a-5cd3-8ce6-2a91e6f32eea', 'Brasil', 'Serra Gaúcha', array['Tannat', 'Cabernet Sauvignon', 'Merlot']::text[], 'seco'::public.wine_sweetness, null, 13.0, '16–18 °C', array['Carnes vermelhas', 'Massas ao sugo', 'Queijos curados']::text[], 'Amora, especiarias e couro; cassis, pimentão e um toque de cedro', 'Estrutura marcante, taninos presentes', 4, 3, 4, 1, null, true),
  ('5b1be1f9-1448-5957-af82-1169b647e1fc', 'alianca-chardonnay', 'Aliança Chardonnay', null, 'Elaborado por Vinícola Nova Aliança (Serra Gaúcha, Brasil) a partir de Chardonnay. No nariz, abacaxi, pêssego e flores brancas. Na boca, frescor equilibrado.', '3269fdb3-5616-542a-9a54-fa4dacaf2db8', 'b4c08ac6-d72a-5cd3-8ce6-2a91e6f32eea', 'Brasil', 'Serra Gaúcha', array['Chardonnay']::text[], 'seco'::public.wine_sweetness, null, 12.0, '8–10 °C', array['Peixes', 'Frutos do mar', 'Saladas']::text[], 'Abacaxi, pêssego e flores brancas', 'Frescor equilibrado', 2, 4, 1, 1, null, false),
  ('63477fb8-836f-500e-8874-f367903d490d', 'alianca-pinot-noir', 'Aliança Pinot Noir', null, 'Elaborado por Vinícola Nova Aliança (Serra Gaúcha, Brasil) a partir de Pinot Noir. No nariz, cereja, framboesa e terra úmida. Na boca, corpo leve e acidez viva.', '2df85ef0-df3f-5ed0-9dd9-b6e049b22e80', 'b4c08ac6-d72a-5cd3-8ce6-2a91e6f32eea', 'Brasil', 'Serra Gaúcha', array['Pinot Noir']::text[], 'seco'::public.wine_sweetness, null, 13.0, '16–18 °C', array['Carnes vermelhas', 'Massas ao sugo', 'Queijos curados']::text[], 'Cereja, framboesa e terra úmida', 'Corpo leve e acidez viva', 2, 3, 2, 1, null, false),
  ('814bccf5-a18d-560e-ad5e-d6dfae9f861f', 'alianca-moscato', 'Aliança Moscato', null, 'Elaborado por Vinícola Nova Aliança (Serra Gaúcha, Brasil) a partir de Moscato. No nariz, flores brancas, pêssego e uva fresca. Na boca, doçura delicada.', '3269fdb3-5616-542a-9a54-fa4dacaf2db8', 'b4c08ac6-d72a-5cd3-8ce6-2a91e6f32eea', 'Brasil', 'Serra Gaúcha', array['Moscato']::text[], 'suave'::public.wine_sweetness, null, 12.0, '8–10 °C', array['Peixes', 'Frutos do mar', 'Saladas']::text[], 'Flores brancas, pêssego e uva fresca', 'Doçura delicada', 2, 4, 1, 4, null, false),
  ('85312a10-973b-5d5e-8e7a-c3b58f305860', 'cerro-da-cruz-tinto', 'Cerro da Cruz Tinto', 'Tintos de entrada com caráter gaúcho', 'Elaborado por Vinícola Nova Aliança (Serra Gaúcha, Brasil) a partir de Tannat, Merlot e Cabernet Sauvignon. No nariz, amora, especiarias e couro; ameixa madura e chocolate. Na boca, estrutura marcante, taninos presentes. Disponível em Tannat, Merlot e Cabernet Sauvignon.', '2df85ef0-df3f-5ed0-9dd9-b6e049b22e80', 'b4c08ac6-d72a-5cd3-8ce6-2a91e6f32eea', 'Brasil', 'Serra Gaúcha', array['Tannat', 'Merlot', 'Cabernet Sauvignon']::text[], 'seco'::public.wine_sweetness, null, 13.0, '16–18 °C', array['Carnes vermelhas', 'Massas ao sugo', 'Queijos curados']::text[], 'Amora, especiarias e couro; ameixa madura e chocolate', 'Estrutura marcante, taninos presentes', 4, 3, 4, 1, null, false),
