  ('8eeead91-9eaf-5216-9ff4-abb02847d2af', 'corbelli-primitivo-di-puglia', 'Corbelli Primitivo di Puglia', 'Puglia em garrafa: intenso e solar', 'Elaborado por Castellani (Sicília, Itália) a partir de Primitivo. No nariz, frutas em compota e especiarias doces. Na boca, corpo cheio.', '2df85ef0-df3f-5ed0-9dd9-b6e049b22e80', 'd59deaa8-98b3-5602-bb07-818df469ca2c', 'Itália', 'Sicília', array['Primitivo']::text[], 'seco'::public.wine_sweetness, null, 13.0, '16–18 °C', array['Carnes vermelhas', 'Massas ao sugo', 'Queijos curados']::text[], 'Frutas em compota e especiarias doces', 'Corpo cheio', 4, 3, 3, 1, null, false),
  ('23b322d7-8279-5e85-9251-a86ccbaa2f3b', 'lourinho-branco-meio-seco', 'Lourinho Branco Meio Seco', null, 'Elaborado por Lourinho (Alentejo, Portugal) a partir de Antão Vaz e Roupeiro. No nariz, frutas frescas e notas florais. Na boca, equilíbrio entre fruta e frescor.', '3269fdb3-5616-542a-9a54-fa4dacaf2db8', '4a3a6cca-9720-5459-90fc-19de4c33cfe9', 'Portugal', 'Alentejo', array['Antão Vaz', 'Roupeiro']::text[], 'meio_seco'::public.wine_sweetness, null, 12.0, '8–10 °C', array['Peixes', 'Frutos do mar', 'Saladas']::text[], 'Frutas frescas e notas florais', 'Equilíbrio entre fruta e frescor', 2, 4, 1, 2, 'Exclusivo', false),
  ('e674abaf-87af-5592-8dca-5489e1fe6819', 'lourinho-tinto-meio-seco', 'Lourinho Tinto Meio Seco', null, 'Elaborado por Lourinho (Alentejo, Portugal) a partir de Aragonez e Trincadeira. No nariz, frutas frescas e notas florais. Na boca, equilíbrio entre fruta e frescor.', '2df85ef0-df3f-5ed0-9dd9-b6e049b22e80', '4a3a6cca-9720-5459-90fc-19de4c33cfe9', 'Portugal', 'Alentejo', array['Aragonez', 'Trincadeira']::text[], 'meio_seco'::public.wine_sweetness, null, 13.0, '16–18 °C', array['Carnes vermelhas', 'Massas ao sugo', 'Queijos curados']::text[], 'Frutas frescas e notas florais', 'Equilíbrio entre fruta e frescor', 4, 3, 4, 2, 'Exclusivo', true),
